from hermes_tools import terminal
r=terminal("python3 - <<'PY'
D=[(('01100','00000','11100','11100','00101','00100'),('00101','00000','00111','00000','00001','00001')), (('00101','00001','10111','01110','00101','10100'),('00111','00010','00111','11001','00011','00101')), (('01001','00001','10001','10000','00001','11001'),('00101','00001','00001','00000','01011','00111')), (('00100','01000','11100','11100','11001','10000'),('00100','00001','10111','01111','01111','00111'))]
# Test simple coordinate transforms, shifts, and Boolean cellwise ops against all demos.
import numpy as np
A=np.array([[int(c) for row in x for c in row] for x,y in D]); B=np.array([[int(c) for row in y for c in row] for x,y in D])
print('input-output bit accuracy direct correlations')
for dr in range(-5,6):
 for dc in range(-4,5):
  vals=[]
  for x,y in D:
   a=np.array([[int(c) for c in row] for row in x]); b=np.array([[int(c) for c in row] for row in y]);
   pred=np.zeros_like(b)
   for r in range(6):
    for c in range(5):
     rr,cc=r+dr,c+dc
     if 0<=rr<6 and 0<=cc<5: pred[r,c]=a[rr,cc]
   vals.extend((pred==b).flat)
  score=sum(vals)
  if score>=75: print((dr,dc),score)
# correlation each output coordinate with each input coordinates, top lags
for op in ['same','not']:
 print(op)
# Try output equals xor/or of translated inputs; brute all pairs of shifts under boundaries.
shifts=[(r,c) for r in range(-5,6) for c in range(-4,5)]
def shifted(a,s):
 dr,dc=s; p=np.zeros_like(a)
 for r in range(6):
  for c in range(5):
   if 0<=r+dr<6 and 0<=c+dc<5:p[r,c]=a[r+dr,c+dc]
 return p
for op in [np.bitwise_xor,np.bitwise_or,np.bitwise_and]:
 best=[]
 for s1 in shifts:
  for s2 in shifts:
   ok=0
   for x,y in D:
    a=np.array([[int(c) for c in row] for row in x]); b=np.array([[int(c) for c in row] for row in y]); ok+=(op(shifted(a,s1),shifted(a,s2))==b).sum()
   best.append((ok,s1,s2))
 print(op.__name__,sorted(best,reverse=True)[:4])
PY")
print(r['output'])

def life(a,toroid=False):
 h=len(a);w=len(a[0]);b=[]
 for r in range(h):
  row=''
  for c in range(w):
   n=0
   for dr in [-1,0,1]:
    for dc in [-1,0,1]:
     if dr==dc==0:continue
     rr=r+dr;cc=c+dc
     if toroid: rr%=h;cc%=w
     if 0<=rr<h and 0<=cc<w: n+=int(a[rr][cc])
   row += '1' if n==3 or (a[r][c]=='1' and n==2) else '0'
  b.append(row)
