from hermes_tools import terminal
r=terminal("python3 - <<'PY'
D=[(('01100','00000','11100','11100','00101','00100'),('00101','00000','00111','00000','00001','00001')), (('00101','00001','10111','01110','00101','10100'),('00111','00010','00111','11001','00011','00101')), (('01001','00001','10001','10000','00001','11001'),('00101','00001','00001','00000','01011','00111')), (('00100','01000','11100','11100','11001','10000'),('00100','00001','10111','01111','01111','00111'))]
def solve(n,eq):
 arr=[sum((v&1)<<i for i,v in enumerate(x)) | (b<<n) for x,b in eq];p=0;piv=[]
 for c in range(n):
  k=next((k for k in range(p,len(arr)) if arr[k]>>c&1),None)
  if k is None:continue
  arr[p],arr[k]=arr[k],arr[p]
  for q in range(len(arr)):
   if q!=p and arr[q]>>c&1:arr[q]^=arr[p]
  piv.append(c);p+=1
 bad=any((z&((1<<n)-1))==0 and z>>n&1 for z in arr)
 ans=[0]*n
 if not bad:
  for ri,c in enumerate(piv):ans[c]=arr[ri]>>n&1
 return bad,len(piv),ans
test=('01010','10100','11100','10100','10101','01101')
for wrap in [False,True]:
 offsets=[(dr,dc) for dr in range(-5,6) for dc in range(-4,5)]
 eq=[]
 for x,y in D:
  a=[[int(c) for c in s] for s in x];b=[[int(c) for c in s] for s in y]
  for r in range(6):
   for c in range(5):
    row=[]
    for dr,dc in offsets:
     rr,cc=r+dr,c+dc
     if wrap: v=a[rr%6][cc%5]
     else:v=a[rr][cc] if 0<=rr<6 and 0<=cc<5 else 0
     row.append(v)
    eq.append((row,b[r][c]))
 bad,rank,sol=solve(len(offsets),eq);print('wrap',wrap,'inconsistent',bad,'rank',rank)
 if not bad:
  a=[[int(c) for c in s] for s in test];out=[]
  for r in range(6):
   row=''
   for c in range(5):
    z=0
    for bit,(dr,dc) in zip(sol,offsets):
     if bit:z^= a[(r+dr)%6][(c+dc)%5] if wrap else (a[r+dr][c+dc] if 0<=r+dr<6 and 0<=c+dc<5 else 0)
    row+=str(z)
   out.append(row)
  print('solution offsets',[(o) for s,o in zip(sol,offsets) if s], 'test',','.join(out))
PY")
